#!/bin/sh
# index.html + icon-180.png -> hako_web.h, the bundle hako links into the binary.
#
# od instead of xxd: xxd ships with vim and is missing on plenty of minimal
# systems (Alpine, iSh), and this has to run wherever the studio is built.
# The output is a plain byte array, so no escaping rules can bite — and the icon
# is binary, so lengths come from sizeof, never strlen.
set -e

SRC=${1:-index.html}
DST=${2:-../hako-code/hako_web.h}
ICON=${3:-icon-180.png}

[ -f "$SRC" ] || { echo "embed: no $SRC" >&2; exit 1; }

# A hash of the source, recorded in the output. A generated file that has fallen
# behind its source is invisible otherwise — the build succeeds and ships a UI
# nobody meant to ship.
src_hash() {
	if command -v shasum >/dev/null 2>&1; then shasum -a 256 "$1" | cut -c1-16
	elif command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -c1-16
	else wc -c < "$1" | tr -d ' '
	fi
}

emit_bytes() {
	od -An -v -tu1 "$1" | awk '
		{ for (i = 1; i <= NF; i++) { printf "%s,", $i; if (++n % 20 == 0) printf "\n" } }
		END { printf "\n" }'
}

{
	printf '/* Generated by hako-studio/tools/embed.sh — do not edit.\n'
	printf '   index.html %s bytes, %s */\n' "$(wc -c < "$SRC" | tr -d ' ')" "$(date -u '+%Y-%m-%d')"
	printf '#define HAKO_WEB_SRC_HASH "%s"\n' "$(src_hash "$SRC")"
	printf 'static const char HAKO_WEB_INDEX[] = {\n'
	emit_bytes "$SRC"
	printf '0 };\n'

	if [ -f "$ICON" ]; then
		printf '\n/* apple-touch-icon, %s bytes — home-screen icon on iOS/Android. */\n' \
			"$(wc -c < "$ICON" | tr -d ' ')"
		printf '#define HAKO_WEB_HAVE_ICON 1\n'
		printf 'static const unsigned char HAKO_WEB_ICON[] = {\n'
		emit_bytes "$ICON"
		printf '0 };\n'
	fi
} > "$DST"

echo "embedded $SRC${ICON:+ + $ICON} -> $DST ($(wc -c < "$DST" | tr -d ' ') bytes of C)"
